#!/usr/bin/env python3
"""Convert numbers between arbitrary bases (2–36)."""

import sys


DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def encode(value: int, base: int) -> str:
    """Encode a non-negative integer to a string in the given base."""
    if base < 2 or base > 36:
        raise ValueError(f"Base must be 2-36, got {base}")
    if value == 0:
        return "0"
    negative = value < 0
    value = abs(value)
    chars: list[str] = []
    while value:
        value, rem = divmod(value, base)
        chars.append(DIGITS[rem])
    if negative:
        chars.append("-")
    return "".join(reversed(chars))


def decode(text: str, base: int) -> int:
    """Decode a string in the given base to an integer."""
    if base < 2 or base > 36:
        raise ValueError(f"Base must be 2-36, got {base}")
    text = text.strip().upper()
    negative = text.startswith("-")
    if negative:
        text = text[1:]
    value = 0
    for ch in text:
        digit = DIGITS.index(ch)
        if digit >= base:
            raise ValueError(f"Invalid digit '{ch}' for base {base}")
        value = value * base + digit
    return -value if negative else value


def convert(number: str, from_base: int, to_base: int) -> str:
    """Convert a number string from one base to another."""
    return encode(decode(number, from_base), to_base)


# ── CLI ──────────────────────────────────────────────────────────────
USAGE = """\
Usage: base_converter.py <number> <from_base> <to_base>

  number     The number to convert (digits 0-9, A-Z)
  from_base  Source base (2-36)
  to_base    Target base (2-36)

Example:
  python base_converter.py FF 16 2   → 11111111
  python base_converter.py 255 10 8  → 377
"""


def main() -> None:
    if len(sys.argv) != 4 or sys.argv[1] in ("-h", "--help"):
        print(USAGE)
        sys.exit(0 if "--help" in sys.argv or "-h" in sys.argv else 1)
    number, from_base_s, to_base_s = sys.argv[1], sys.argv[2], sys.argv[3]
    try:
        from_base = int(from_base_s)
        to_base = int(to_base_s)
        result = convert(number, from_base, to_base)
        print(result)
    except (ValueError, IndexError) as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
